import { SheetBody } from '../../slots/defs/sheetBody';
import { useActive } from '../active/useActive';
import { useClaims } from '../claims/useClaims';
import { GRADES, usePeople } from '../people/usePeople';
import { usePeriodDueTotals } from '../periods/usePeriodDueTotals';
import { usePeriods } from '../periods/usePeriods';
import { useSettings } from '../settings/useSettings';
import { useDueTotals } from '../rates/useDueTotals';
import { hundredths, money, sumDues } from '../rates/useRates';
import { countWithStatus, STATUSES } from './statusCounts';
import { useFigure } from '../locale/useLocale';

/** The sheet's summary, worked out from the same figures the lists show: per grade, how many people
 *  have it on the sheet's today (retired people left out) and their due-totals added up (skipping
 *  'n/a') and how many of them are active; per period, its due-total and its change from the period before it by from-date (none for the earliest); per status, how many claims have it, and how many REVIEW claims are review-late; per void reason on the
 *  sheet's list, how many VOID claims were voided with it. */
function Summary({ sheetId }: { sheetId: string }) {
  const fig = useFigure();
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const dueTotals = useDueTotals(sheetId);
  const periodTotals = usePeriodDueTotals(sheetId);
  const activeById = useActive(sheetId);
  const voidReasons = useSettings(sheetId).data?.voidReasons ?? [];
  const current = (people.data ?? []).filter((p) => !p.retiredFrom);
  const byFrom = [...(periods.data ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const changes = new Map<string, string>();
  byFrom.forEach((p, i) => {
    if (i === 0) return;
    const prev = periodTotals.get(byFrom[i - 1].name) ?? '0.00';
    changes.set(p.name, money(hundredths(periodTotals.get(p.name) ?? '0.00') - hundredths(prev)));
  });
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {fig(sumDues(onGrade.map((p) => dueTotals.get(p.id) ?? 'n/a')))}
                </td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => activeById.get(p.id)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{fig(periodTotals.get(p.name) ?? '')}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{fig(changes.get(p.name) ?? '')}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>
                {countWithStatus(claims.data, s)}
              </td>
            </tr>
          ))}
          <tr>
            <td>Review late</td>
            <td data-testid="summary-review-late-count">{(claims.data ?? []).filter((c) => c.reviewLate).length}</td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r}>
              <td>{r}</td>
              <td data-testid={`summary-void-${r}-count`}>
                {(claims.data ?? []).filter((c) => c.status === 'VOID' && c.voidReason === r).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 40, Component: ({ sheetId }) => <Summary sheetId={sheetId} /> });
import { type Claim, counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, type Person, usePeople } from '../people/usePeople';
import { type Settings, settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, type Rate, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims left out once their retirement date is reached (a hold leaves none out) unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's settled-total and open-total, by person id: the sum of the figures of their counting SETTLED
 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
 *  The two add up to the due-total before the cap. */
export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
  const split = new Map<number, { settled: string; open: string }>();
  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
  return split;
}

/** Each person's due-total held to the cap, their excess over it, and its settled and open parts. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  return dueFigures(people.data, claims.data, rates.data, settings, today.data?.today);
}

/** Each person's due-total, by person id, from these people, claims, rates and settings on this today (as
 *  useDueTotals shows them). */
export function dueTotalsOf(...args: Parameters<typeof dueFigures>): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of dueFigures(...args)) totals.set(id, f.total);
  return totals;
}

function dueFigures(
  people: Person[] | undefined,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  settings: Settings | undefined,
  today: string | undefined,
): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const holds = holdsById(people, today);
  const cap = settingOn(settings, 'cap', today);
  const totals = new Map<number, { total: string; excess: string; settled: string; open: string }>();
  for (const p of people ?? []) {
    const counting = (claims ?? []).filter((c) => c.personId === p.id && counts(c, holds, today));
    const rated = rateFor(rates, p.grade, today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims, rateFor(rates, gradeOn(p, c.date), c.date, c.added), settings, today, gradeOn(p, c.date)));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
    });
  }
  return totals;
